import re,json
from html.parser import HTMLParser
from pathlib import Path
class P(HTMLParser):
 skip=False
 def handle_starttag(self,t,a):
  if t=='script': self.skip=True
  if t=='a': print('LINK',dict(a).get('href'))
 def handle_endtag(self,t):
  if t=='script': self.skip=False
 def handle_data(self,d):
  if not self.skip and d.strip(): print(d.strip())
s=Path('products/research/paid-review-contests/sherlock-bounties.html').read_text();P().feed(s)
parts=[]
for m in re.finditer(r'self\.__next_f\.push\((\[.*?\])\)</script>',s):
 try:
  x=json.loads(m.group(1))
  if len(x)>1 and isinstance(x[1],str):parts.append(x[1])
 except ValueError:pass
s=''.join(parts)
for term in ['bounties','ACTIVE','active','prize','reward','USDC']:
 print(term,[s[max(0,m.start()-100):m.start()+500] for m in list(re.finditer(term,s))[:3]])
